#!/bin/bash
# i5.sh: evidence items never run before.
. "$(dirname "$0")/lib-b.sh"
exec >> raw/i5-evidence.txt 2>&1
TEN=t:0:300
echo "=== 5a. Reads through lenny-evidence from a named position"
reset_store; ev_start 1 0; ev_start 2 1; dec_start; envoy_start als; /bin/sleep 1; rm -f work/consume.txt work/cursor.json work/export.txt; psqld "insert into evidence_consumer_reg(consumer) values('siem')"
load -rate 1000 -for 45s -tenants 300 -busy 3 -warm 0s | sumfmt; wait_queue; flush_all; wait_empty; /bin/sleep 2
echo "--- the allowlist"; TOOL readprobe -tenant t1 -leaf /certs/lenny-egress-authz 2>&1 | tail -1 | cut -c1-120; TOOL readprobe -tenant t1 -leaf /certs/foreign-authz 2>&1 | tail -1 | cut -c1-200; TOOL readprobe -tenant t1 2>&1 | tail -1 | cut -c1-160
INC=$(dec_stats | grep -o '"incarnation":"[^"]*"' | cut -d'"' -f4); POS="t1 egress.decision lenny-egress-authz.lenny-system.svc $INC"; N=$(psqld "select max(seq_last)/2 from manifest where tenant_id='t1' and stream='egress.decision'")
echo "--- from a named position: sequence $N at the producer's position"; TOOL readprobe -tenant t1 -pos "$POS" -seq $N 2>&1 | tail -1 | cut -c1-200
echo "--- a consumer that dies part way, while compaction runs and more arrives"
(load -rate 1000 -for 40s -tenants 300 -busy 3 -warm 0s | sumfmt) &
/bin/sleep 3; TOOL consume -urls https://198.19.0.31:8443 -consumer siem -stream egress.decision -tenants $TEN -limit 2000 -max 20000 2>&1 | tail -1 | cut -c1-200
(for i in 1 2 3; do TOOL compact -par 8 2>&1 | tail -1 | cut -c1-120; /bin/sleep 8; done) &
TOOL consume -urls https://198.19.0.31:8443,https://198.19.0.32:8443 -consumer siem -stream egress.decision -tenants $TEN -limit 2000 2>&1 | tail -1 | cut -c1-200
wait; wait_queue; flush_all; wait_empty; /bin/sleep 2
TOOL consume -urls https://198.19.0.32:8443 -consumer siem -stream egress.decision -tenants $TEN -limit 2000 2>&1 | tail -1 | cut -c1-200; TOOL exportcheck -in /w/consume.txt -stream egress.decision 2>&1 | tail -6 | cut -c1-220
echo "   read cost: $(for n in 1 2; do ev_stats $n | grep -o '"readRecords":[0-9]*\|"readRetries":[0-9]*' | tr '\n' ' '; done)"; echo "   rows now $(psqld "select count(*) from manifest where stream='egress.decision'"), positions in stored cursors: $(psqld "select sum((select count(*) from jsonb_object_keys(cursor))), max(pg_column_size(cursor)) from evidence_consumers")"
echo "--- a replica restarted under load, with two writers for a position: the high-water cursor against the ranges cursor"
reset_store; ev_start 1 0 -e FLUSH=5s; ev_start 2 1 -e FLUSH=5s; dec_start; envoy_start als; /bin/sleep 1; rm -f work/consume.txt work/cursor.json work/export.txt; psqld "insert into evidence_consumer_reg(consumer) values('siem')"
(/bin/sleep 20; docker stop -t 30 od-ev2 >/dev/null; ev_start 2 1 -e FLUSH=5s; /bin/sleep 12; docker stop -t 30 od-ev1 > /dev/null; ev_start 1 0 -e FLUSH=5s) &
(for i in 1 2 3 4 5 6; do /bin/sleep 8; TOOL export 2>&1 | tail -1 | cut -c1-110; done) &
load -rate 1000 -for 55s -tenants 300 -busy 3 -warm 0s | sumfmt; wait; wait_queue; flush_all; wait_empty; /bin/sleep 3; TOOL export 2>&1 | tail -1 | cut -c1-110
echo "   high-water cursor (the earlier export), read while batches landed: $(TOOL exportcheck -in /w/export.txt 2>&1 | tail -1 | cut -c1-200)"; TOOL consume -urls https://198.19.0.31:8443 -consumer siem -stream egress.decision -tenants $TEN -limit 5000 2>&1 | tail -1 | cut -c1-160; for s in egress.tunnel egress.accesslog; do TOOL consume -urls https://198.19.0.31:8443 -consumer siem -stream $s -tenants $TEN -limit 5000 2>&1 | tail -1 | cut -c1-160; done; echo "   ranges cursor through the service: $(TOOL exportcheck -in /w/consume.txt -stream egress.decision 2>&1 | tail -1 | cut -c1-200)"; timeline | sed 's/^/   /' | cut -c1-150 | head -8; TOOL gaps -truth http://198.19.0.11:9002/positions -stream egress.decision 2>&1 | tail -2 | cut -c1-360
echo "=== 5b. Retention by consumer position, and holds"
reset_store; ev_start 1 0 -e FLUSH=5s; ev_start 2 1 -e FLUSH=5s; dec_start; envoy_start als; /bin/sleep 1; rm -f work/consume.txt; psqld "insert into evidence_consumer_reg(consumer) values('siem')"
load -rate 300 -for 25s -tenants 30 -busy 2 -warm 0s | sumfmt; wait_queue; flush_all; wait_empty; /bin/sleep 8
TOOL consume -urls https://198.19.0.31:8443 -consumer siem -stream egress.decision -tenants t:0:30 -limit 200 -max 1500 2>&1 | tail -1 | cut -c1-140
psqld "update manifest set held=true where tenant_id='t7'" >/dev/null 2>&1; docker exec od-pg psql -q -tA -U postgres -c "begin; select set_config('app.current_tenant','__all__',true); update manifest set held=true where tenant_id='t7'; commit;" >/dev/null; echo "   held rows for t7: $(psqld "select count(*) from manifest where tenant_id='t7' and held")"
R0=$(psqld "select count(*) from manifest where stream='egress.decision'"); echo "   decision rows before retention: $R0"
echo "--- retention at 5 s, consumer bound 1 h: rows the consumer has not read stay"; TOOL retain -stream egress.decision -age 5s -bound 1h 2>&1 | tail -1 | cut -c1-240; echo "   rows now $(psqld "select count(*) from manifest where stream='egress.decision'")"; TOOL verify 2>&1 | tail -1 | cut -c1-300
echo "--- the consumer finishes, retention runs again"; TOOL consume -urls https://198.19.0.31:8443 -consumer siem -stream egress.decision -tenants t:0:30 -limit 2000 2>&1 | tail -1 | cut -c1-140; TOOL retain -stream egress.decision -age 5s -bound 1h 2>&1 | tail -1 | cut -c1-240; echo "   decision rows now: $(psqld "select count(*) from manifest where stream='egress.decision'"), of which held: $(psqld "select count(*) from manifest where stream='egress.decision' and held")"; TOOL verify 2>&1 | tail -1 | cut -c1-300
echo "--- the delivered set against what retention removed: nothing the consumer had not read is gone"; TOOL exportcheck -in /w/consume.txt -stream egress.decision 2>&1 | tail -1 | cut -c1-200
echo "--- a consumer that stops reading: past the bound the row goes and the loss is recorded"; psqld "insert into evidence_consumer_reg(consumer) values('stalled')"; TOOL retain -stream egress.tunnel -age 5s -bound 1h 2>&1 | tail -1 | cut -c1-240; TOOL retain -stream egress.tunnel -age 5s -bound 6s 2>&1 | tail -1 | cut -c1-240; echo "   loss rows per consumer: $(psqld "select consumer, count(*) from evidence_consumer_loss group by 1" | tr '\n' ' ')"
echo "--- retention with no chain event"; TOOL retain -stream egress.accesslog -age 5s -bound 6s -tombstone=false -honour-consumers=false 2>&1 | tail -1 | cut -c1-200; docker exec od-client wget -qO- http://198.19.0.31:9100/anchor >/dev/null; TOOL verify 2>&1 | tail -1 | cut -c1-300; echo "   anchors naming a removed batch: $(TOOL verify 2>&1 | grep -c 'NOT IN THE MANIFEST')"
echo "--- holds and the compactor, retention, and DeleteByTenant"
reset_store; ev_start 1 0 -e FLUSH=3s -e CHUNK=1; ev_start 2 1 -e FLUSH=3s -e CHUNK=1; dec_start; envoy_start als; /bin/sleep 1
load -rate 300 -for 25s -tenants 30 -busy 2 -warm 0s | sumfmt; docker exec od-client wget -qO- "http://198.19.0.11:9002/activity?tenant=t7&n=400&session=sh" >/dev/null; docker exec od-client wget -qO- "http://198.19.0.11:9002/activity?tenant=t8&n=400&session=sz" >/dev/null; wait_queue; flush_all; wait_empty; /bin/sleep 2
H(){ docker exec od-pg psql -q -tA -U postgres -c "begin; select set_config('app.current_tenant','__all__',true); update manifest set held=$2 where tenant_id='$1'; commit;" >/dev/null; }
H t7 true; A7=$(psqld "select count(*)||' rows, digests '||md5(string_agg(digest,',' order by id)) from manifest where tenant_id='t7'"); echo "   t7 before: $A7"
TOOL compact -par 8 2>&1 | tail -1 | cut -c1-170; echo "   t7 after the compactor: $(psqld "select count(*)||' rows, digests '||md5(string_agg(digest,',' order by id)) from manifest where tenant_id='t7'"), compacted t7 rows $(psqld "select count(*) from manifest where tenant_id='t7' and compacted"), compacted t8 rows $(psqld "select count(*) from manifest where tenant_id='t8' and compacted")"
TOOL retain -stream egress.decision -age 1s -bound 2s -honour-consumers=false 2>&1 | tail -1 | cut -c1-200; echo "   t7 decision rows after retention: $(psqld "select count(*) from manifest where tenant_id='t7' and stream='egress.decision'")"
echo "   hold on t7, DeleteByTenant t7 and t8:"; TOOL deletetenant -tenant t7 2>&1 | tail -1 | cut -c1-200; TOOL deletetenant -tenant t8 2>&1 | tail -1 | cut -c1-200; echo "   rows left: t7 $(psqld "select count(*) from manifest where tenant_id='t7'") t8 $(psqld "select count(*) from manifest where tenant_id='t8'"); chain rows t7 $(psqld "select count(*) from audit_chain where tenant_id='t7'") t8 $(psqld "select count(*) from audit_chain where tenant_id='t8'")"; echo "   held t7 payloads still readable: $(TOOL erase 2>&1 | tail -1 | cut -c1-220)"
TOOL verify 2>&1 | tail -1 | cut -c1-300
echo "   session erasure under a hold: destroying the held session's key"; docker exec od-client wget -qO- 'http://198.19.0.31:9100/keys/destroy?tenant=t7&session=sh' ; echo "   held t7 payloads after that: $(TOOL erase 2>&1 | tail -1 | cut -c1-220)"
H t7 false; TOOL compact -par 8 2>&1 | tail -1 | cut -c1-140; TOOL deletetenant -tenant t7 2>&1 | tail -1 | cut -c1-200; echo "   hold released, deleted: t7 rows $(psqld "select count(*) from manifest where tenant_id='t7'") objects $(docker exec od-mc sh -c 'mc ls -r m/evidence/t7/ 2>/dev/null | wc -l')"
echo "   records after DeleteByTenant recreate the tenant's rows: "; docker exec od-client wget -qO- "http://198.19.0.11:9002/activity?tenant=t8&n=50&session=sz" >/dev/null; wait_queue; flush_all; wait_empty; /bin/sleep 2; echo "   t8 rows $(psqld "select count(*) from manifest where tenant_id='t8'")"
echo "--- a hold set during compaction and during retention"
reset_store; ev_start 1 0 -e FLUSH=1s; ev_start 2 1 -e FLUSH=1s; dec_start; envoy_start als; /bin/sleep 1; load -rate 1000 -for 30s -tenants 400 -busy 2 -warm 0s | sumfmt; wait_queue; flush_all; wait_empty; /bin/sleep 2; echo "   rows $(psqld "select count(*) from manifest")"
(for i in $(seq 1 30); do H t$((RANDOM%400)) true; /bin/sleep 0.15; done) & TOOL compact -par 8 2>&1 | tail -4 | cut -c1-200; wait; echo "   held rows: $(psqld "select count(*) from manifest where held"), held and compacted: $(psqld "select count(*) from manifest where held and compacted")"; TOOL verify 2>&1 | tail -1 | cut -c1-280
echo "=== 5c. More than one decision service replica"
twodec(){ reset_store; ev_start 1 0; ev_start 2 1; dec_start 1 "$@"; dec_start 2 "$@"; envoy_start als2; /bin/sleep 1; }
TR=http://198.19.0.11:9002/positions,http://198.19.0.12:9002/positions
echo "--- steady: 2,000/s, 2,500 tenants, 25 regulated, 150 s"; twodec -e REG_MOD=100; B=$(cg od-envoy od-dec1 od-dec2 od-ev1 od-ev2); load -rate 2000 -for 150s | sumfmt; A=$(cg od-envoy od-dec1 od-dec2 od-ev1 od-ev2); cgdiff "$B" "$A" 150; for n in 1 2; do destat $n; done; wait_queue 1; wait_queue 2; flush_all; wait_empty; /bin/sleep 2; TOOL gaps -truth $TR 2>&1 | tail -2 | cut -c1-380; echo "   producer values and incarnations per stream: $(psqld "select stream, count(distinct producer), count(distinct incarnation) from manifest group by 1" | tr '\n' ' ')"; echo "   manifest rows $(psqld "select count(*) from manifest")"
rm -f work/export.txt work/cursor.json; TOOL compact -par 8 2>&1 | tail -1 | cut -c1-150; TOOL verify 2>&1 | tail -1 | cut -c1-280
echo "--- SIGKILL of one decision replica at t=40 s, restart at t=50 s, load to t=90 s"; twodec -e REG_MOD=100; (/bin/sleep 40; docker kill od-dec2 >/dev/null; echo "   killed at $(now)"; /bin/sleep 10; dec_start 2 -e REG_MOD=100; echo "   restarted at $(now)") & load -rate 2000 -for 90s -warm 0s | sumfmt; wait; wait_queue 1; wait_queue 2; flush_all; wait_empty; /bin/sleep 3; for n in 1 2; do destat $n; done; TOOL gaps -truth $TR 2>&1 | tail -2 | cut -c1-380; echo "   incarnations in the decision stream: $(psqld "select count(distinct incarnation) from manifest where stream='egress.decision'"), closing records: $(psqld "select 0")"
echo "   stored decisions against the two producers' current counts; the killed incarnation's truth is gone with it: $(psqld "select incarnation, sum(records) from manifest where stream='egress.decision' group by 1" | tr '\n' ' ')"
echo "--- SIGTERM of one decision replica at t=30 s, load to t=60 s: closing records"; twodec; (/bin/sleep 30; docker stop -t 25 od-dec2 >/dev/null; echo "   stopped at $(now)"; ) & load -rate 2000 -for 60s -warm 0s | sumfmt; wait; wait_queue 1; flush_all; wait_empty; /bin/sleep 3; destat 1; TOOL gaps -truth http://198.19.0.11:9002/positions 2>&1 | tail -2 | cut -c1-380
echo "=== 5d. egress.local, git.operation, and credential.mint under load"
ALL=$(docker exec od-py python3 -c 'print(",".join("t%d"%i for i in range(2500)))')
strm(){ L=$1; shift; echo "--- $L"; reset_store; MIRRORS=$ALL ev_start 1 0; MIRRORS=$ALL ev_start 2 1; dec_start -e REG_MOD=100; envoy_start als; /bin/sleep 1; C="od-envoy od-dec1 od-ev1 od-ev2 od-pg od-minio"; B=$(cg $C); }
strm "baseline, 2,000 CONNECTs/s, no other producers, 180 s"; load -rate 2000 -for 180s | sumfmt; A=$(cg $C); cgdiff "$B" "$A" 180; evstat 1; evstat 2
strm "with egress.local 2,000/s through I7, git.operation 200/s from the mirror, and credential.mint 33/s from the Token Service, 180 s"
(TOOL gen2 local -rate 2000 -for 180s 2>&1 | tail -1 | cut -c1-200) & (TOOL gen2 gitop -rate 200 -for 180s 2>&1 | tail -1 | cut -c1-200) & (TOOL gen2 mint -rate 40 -for 180s 2>&1 | tail -1 | cut -c1-200) &
load -rate 2000 -for 180s | sumfmt; wait; A=$(cg $C); cgdiff "$B" "$A" 180; wait_queue; flush_all; wait_empty; /bin/sleep 3; destat; evstat 1; evstat 2; echo "   local reports refused: $(dec_stats | grep -o '"localRefused":[0-9]*') accepted: $(dec_stats | grep -o '"local":[0-9]*')"
TOOL gaps -truth http://198.19.0.11:9002/positions 2>&1 | tail -2 | cut -c1-420
echo "   per stream (rows, records, stored, percent of raw, mean record bytes):"; psqld "select stream, count(*), sum(records), pg_size_pretty(sum(bytes)), round(100.0*sum(bytes)/sum(raw_bytes),1), round(1.0*sum(raw_bytes)/sum(records)) from manifest group by 1 order by 1"
echo "   time to durable p50 and p99, by stream: "; psqld "select stream, round(extract(epoch from percentile_cont(.5) within group (order by created_at-time_first))::numeric,1), round(extract(epoch from percentile_cont(.99) within group (order by created_at-time_first))::numeric,1) from manifest group by 1 order by 1"
echo "   forged fields in stored egress.local: tenant forged-tenant rows $(psqld "select count(*) from manifest where tenant_id='forged-tenant'")"
echo "   provenance sample: $(docker exec od-mc sh -c 'mc find m/evidence/t0/evidence/egress.local --maxdepth 3 2>/dev/null | head -1 | xargs -I{} mc cat {}' 2>/dev/null | gzip -dc 2>/dev/null | head -1 | cut -c1-320)"
echo "--- refused shapes"; docker exec od-client sh -c 'for b in "[{\"stream\":\"egress.local\",\"sessionId\":\"not-bound\",\"payload\":{}}]" "[{\"stream\":\"egress.decision\",\"payload\":{}}]" "[{\"stream\":\"egress.local\",\"tenantId\":\"t9\",\"podUid\":\"x\",\"payload\":{\"event\":\"ok\"}}]"; do wget -qO- --header "Authorization: Bearer t5/0" --post-data "$b" http://198.19.0.11:9004/v1/report; done'; docker exec od-client sh -c 'wget -qO- --post-data "[]" http://198.19.0.11:9004/v1/report 2>&1 | tail -1 | cut -c1-100'
MIRRORS=tmirror ev_start 1 0; MIRRORS=tmirror ev_start 2 1; /bin/sleep 1.5; TOOL probe https://198.19.0.31:8443 2>&1 | cut -c1-140
echo "=== 5e. The one undelivered record of b2: numbering outside the send order, against a high-water cursor"
b2r(){ L=$1; shift; echo "--- $L"; reset_store; ev_start 1 0 -e FLUSH=2s; ev_start 2 1 -e FLUSH=2s; dec_start "$@"; envoy_start als; /bin/sleep 1; rm -f work/export.txt work/cursor.json work/consume.txt
  load -rate 2000 -for 60s -tenants 200 -busy 5 -warm 0s | sumfmt; wait_queue; flush_all; wait_empty; /bin/sleep 3
  echo "   batches starting at or below an earlier batch's last, per stream: $(psqld "with x as (select stream, seq_first, lag(seq_last) over (partition by tenant_id,stream,producer,incarnation order by id) prev from manifest) select stream, count(*) from x where seq_first <= prev group by 1" | tr '\n' ' ')"
  TOOL export -max 100000 2>&1 | tail -1 | cut -c1-120; TOOL export 2>&1 | tail -1 | cut -c1-120; echo "   high-water cursor: $(TOOL exportcheck 2>&1 | tail -6 | cut -c1-170)"; TOOL consume -urls https://198.19.0.31:8443 -consumer c2 -stream egress.decision -tenants t:0:200 -limit 20000 2>&1 | tail -1 | cut -c1-120; echo "   ranges cursor, decision stream: $(TOOL exportcheck -in /w/consume.txt -stream egress.decision 2>&1 | tail -1 | cut -c1-170)"; }
b2r "SEQ_ATOMIC=0: a sequence number is taken, and the record is queued afterwards (rounds 9 to 11)" -e SEQ_ATOMIC=0
b2r "SEQ_ATOMIC=0, again" -e SEQ_ATOMIC=0
b2r "numbering and queueing under one lock" -e SEQ_ATOMIC=1
echo done > raw/i5-done
